import java.util.Scanner;

public class Main {
    static long p1, q1, r1;

    static long computeGCD(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p1 = sc.nextLong();
        q1 = sc.nextLong();
        r1 = sc.nextLong();

        if (q1 <= r1) {
            long g = computeGCD(p1, q1);
            p1 /= g;
            q1 /= g;
            System.out.println(p1 + "/" + q1);
            return;
        }
        if (p1 == q1) {
            System.out.println("1/1");
            return;
        }

        double best_diff = 1e18;
        double ratio = (double) p1 / (double) q1;
        long num = 0, den = 1;
        long left_bound = 0, right_bound = q1;

        for (long i = 1; i <= r1; ++i) {
            while (i * p1 > right_bound) {
                left_bound += q1;
                right_bound += q1;
            }
            if (i * p1 >= left_bound && i * p1 <= right_bound) {
                long low = left_bound / q1;
                long high = right_bound / q1;
                double low_ratio = (double) low / (double) i;
                double high_ratio = (double) high / (double) i;
                double diff_low = Math.abs(ratio - low_ratio);
                double diff_high = Math.abs(ratio - high_ratio);
                if (diff_high < diff_low) {
                    if (diff_high < best_diff) {
                        best_diff = diff_high;
                        num = high;
                        den = i;
                    }
                } else {
                    if (diff_low < best_diff) {
                        best_diff = diff_low;
                        num = low;
                        den = i;
                    }
                }
            }
        }
        long g = computeGCD(num, den);
        num /= g;
        den /= g;
        System.out.println(num + "/" + den);
    }
}
